WITH item_returns AS (SELECT cr.cr_item_sk AS item_sk, cr.cr_net_loss AS net_loss, cr.cr_return_amount AS return_amount FROM catalog_returns cr UNION ALL SELECT sr.sr_item_sk AS item_sk, sr.sr_net_loss AS net_loss, sr.sr_return_amt AS return_amount FROM store_returns sr) SELECT item_sk, SUM(net_loss) AS total_net_loss, AVG(return_amount) AS avg_return_amount, CASE WHEN AVG(return_amount) > 500 THEN 'High' WHEN AVG(return_amount) BETWEEN 200 AND 500 THEN 'Medium' ELSE 'Low' END AS return_value_category, ROW_NUMBER() OVER (ORDER BY SUM(net_loss) DESC) AS net_loss_rank FROM item_returns GROUP BY item_sk HAVING SUM(net_loss) > 0 ORDER BY net_loss_rank LIMIT 10
